//! 🎯️ Native causal targets borrow typed layer or asset identities without cloning a target vector.
use super::RasterMutation;
use semio_framework_value::{ValueError,ValueRefusalKind};
fn parts(operation:&RasterMutation)->[&str;2]{match operation{
 RasterMutation::CreateLayer(value)=>["layer/",semio_s_artifact_raster_raster_model::layer_node_id(&value.layer)],
 RasterMutation::DeleteLayer(value)=>["layer/",&value.layer_id],RasterMutation::ReorderLayers(value)=>["layer/",&value.layer_id],RasterMutation::RenameLayer(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerVisible(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerLocked(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerOpacity(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerBlendMode(value)=>["layer/",&value.layer_id],RasterMutation::MoveLayer(value)=>["layer/",&value.layer_id],RasterMutation::ResizeLayer(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerAdjustmentKind(value)=>["layer/",&value.layer_id],RasterMutation::AddLayerAsset(value)=>["asset/",&value.asset_id],RasterMutation::RemoveLayerAsset(value)=>["asset/",&value.asset_id],RasterMutation::ChangeLayerPixels(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerMask(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerTransform(value)=>["layer/",&value.layer_id],RasterMutation::ChangeLayerAdjustmentParameter(value)=>["layer/",&value.layer_id],RasterMutation::PaintStroke(value)=>["layer/",&value.layer_id],RasterMutation::FillRegion(value)=>["layer/",&value.layer_id],RasterMutation::ApplyFilter(value)=>["layer/",&value.layer_id],RasterMutation::TransformImage(value)=>["layer/",&value.layer_id],RasterMutation::FillSelection(value)=>["layer/",&value.layer_id],RasterMutation::WritePixelRegion(value)=>["layer/",&value.layer_id],
}}
impl semio_framework_os_store_operation_wire::ArtifactOperationTargets for RasterMutation{
 fn len(&self)->usize{1}
 fn segment_len(&self,index:usize)->Result<usize,ValueError>{if index!=0{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"Raster native target ordinal is absent"))}let parts=parts(self);parts[0].len().checked_add(parts[1].len()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"Raster native target length overflow"))}
 fn read_segment(&self,index:usize,mut offset:usize,output:&mut[u8])->Result<usize,ValueError>{let length=semio_framework_os_store_operation_wire::ArtifactOperationTargets::segment_len(self,index)?;if offset>length{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"Raster native target offset is absent"))}let mut written=0;for part in parts(self){if offset>=part.len(){offset-=part.len();continue}let length=(part.len()-offset).min(output.len()-written);output[written..written+length].copy_from_slice(&part.as_bytes()[offset..offset+length]);written+=length;offset=0;if written==output.len(){break}}Ok(written)}
}
#[cfg(test)]mod tests{
 use super::*;
 use semio_framework_os_store_operation_wire::ArtifactOperationTargets;
 #[test]fn native_targets_match_authored_namespace_and_page_boundaries(){let fixture=semio_framework_pack_json::parse(include_str!("fixtures.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixture.get("cases").unwrap().as_array().unwrap(){let mutation:RasterMutation=semio_framework_pack_json::from_json_str(&semio_framework_pack_json::to_string(row.get("input").unwrap()),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut actual=Vec::new();while actual.len()<mutation.segment_len(0).unwrap(){let mut page=[0;3];let n=mutation.read_segment(0,actual.len(),&mut page).unwrap();assert!(n>0);actual.extend_from_slice(&page[..n]);}assert_eq!(std::str::from_utf8(&actual).unwrap(),row.get("target").unwrap().as_str().unwrap());assert!(mutation.read_segment(1,0,&mut[0]).is_err());assert!(mutation.read_segment(0,actual.len()+1,&mut[0]).is_err());super::super::retire_raster_mutation(mutation);}}
}
